#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7
PROFILE="v1be-admin"
REGION="ap-southeast-1"

# Admin logins happen only in Windows Sandbox (ADR-0012). This folder exists
# only there, through the mapping in v1be-admin.wsb.
if [[ ! -d /c/code/v1be-infra/sandbox ]]; then
  warn "Stopping: this isn't Windows Sandbox. Open v1be-admin.wsb and run it there."
  exit 1
fi

banner "IAM Identity Center: Organization and admin user"

# A new Sandbox has no CLI setup, so a later run can go straight to sign-in.
if confirm "Is the admin user already created and assigned (a re-run)?"; then
  _STAGE_INDEX=5
else

stage "Before you start"
warn "This must be the management account, the one with the +management email."
open_url "https://console.aws.amazon.com/billing/home#/account"
step "Sign in as Root user with your +management email."
step "On the Account page, check the email shown is the +management one."
if ! confirm "Does the Account page show your +management email?"; then
  warn "Stopping before anything changes. Sign out and sign in to the right account."
  exit 1
fi

stage "Enable Identity Center in Singapore"
warn "The primary Region can't be changed after this. Check it carefully."
open_url "https://ap-southeast-1.console.aws.amazon.com/singlesignon/home?region=ap-southeast-1"
step "Check the Region selector at the top right says Asia Pacific (Singapore)."
if ! confirm "Does the Region selector say Singapore?"; then
  warn "Stopping before anything changes. Pick Singapore and re-run."
  exit 1
fi
step "If it offers Instance configuration, choose Single-Region instance."
note "Multi-Region adds KMS charges. You can add Regions later."
step "Leave the optional KMS key alone, and leave multi-account permissions on."
step "Choose Enable."
step "If it says it will create an Organization, review it and choose Enable."
pause "Press Enter when the Identity Center dashboard opens."

stage "Add your admin user"
step "In the left menu, choose Users, then Add user."
step "Username: v1be-admin. This can't be changed later."
step "Password: choose Generate a one-time password."
step "Email: your Gmail with +admin before the @."
step "Enter your real first and last name, then Next."
step "Skip groups, choose Next, then Add user."
warn "Keep the page showing the portal URL and one-time password open."
note "Copy the portal URL into your password manager's v1be-admin entry."
step "On the user's page, choose Send email verification link if it's offered."
step "Open that email on your phone and verify."
pause "Press Enter when the user exists."

stage "Give the user admin access"
note "This assigns the user directly, not a group, as AWS advises for this account."
step "In the left menu, choose AWS accounts under Multi-account permissions."
step "Tick your management account, then Assign users or groups."
step "On the Users tab, tick v1be-admin, then Next."
step "Choose Create permission set. A new tab opens."
step "Choose Predefined permission set, then AdministratorAccess, then Next."
step "Keep the defaults, choose Next, then Create, and close that tab."
step "Back on the first tab, refresh, tick AdministratorAccess, then Next."
step "Choose Submit and wait for the success message."
pause "Press Enter when the assignment succeeds."

stage "Stop using root"
step "Choose your account name at the top right, then Sign out."
warn "From here on, use v1be-admin. Keep root for emergencies only."
pause "Press Enter when root is signed out."

fi

stage "First sign-in as v1be-admin"
note "Skip this stage if you've already registered MFA for v1be-admin."
step "Open the portal URL and sign in as v1be-admin."
step "Use the one-time password, then set a new password."
step "Save that password under v1be-admin, and don't let the browser save it."
warn "For MFA, choose Authenticator app, not a passkey."
note "A passkey saved in this Sandbox is deleted when the Sandbox closes."
step "Label the authenticator entry v1be-admin, so it's distinct from root."
step "Check the portal lists your account with AdministratorAccess."
pause "Press Enter when you can see that."

stage "Set up the command line and check it"
say "The AWS CLI asks some questions next. Answer them like this:"
step "SSO session name: v1be"
step "SSO start URL: your portal URL"
step "SSO region: $REGION"
step "SSO registration scopes: press Enter for the default"
step "Approve in the browser when it opens."
step "Default client Region: $REGION, output format: json"
step "Profile name: $PROFILE"
pause "Press Enter to start."
if ! aws configure sso; then
  warn "The browser sign-in didn't finish. Trying the device code instead."
  aws configure sso --use-device-code
fi

ARN=$(aws sts get-caller-identity --profile "$PROFILE" --query Arn --output text 2>/dev/null | tr -d '\r' || true)
FEATURES=$(aws organizations describe-organization --profile "$PROFILE" --query Organization.FeatureSet --output text 2>/dev/null | tr -d '\r' || true)
INSTANCE=$(aws sso-admin list-instances --region "$REGION" --profile "$PROFILE" --query 'Instances[0].Status' --output text 2>/dev/null | tr -d '\r' || true)

FAILED=0
check() {
  if [[ "$2" == *"$3"* ]]; then
    printf '  %sPASS%s %s\n' "$GREEN" "$RESET" "$1"
  else
    printf '  %sFAIL%s %s\n' "$YELLOW" "$RESET" "$1"
    FAILED=1
  fi
}
check "Signed in as the Identity Center admin" "$ARN" "AWSReservedSSO_AdministratorAccess"
check "Organization has all features" "$FEATURES" "ALL"
check "Identity Center is in $REGION" "$INSTANCE" "ACTIVE"
pause "Note the results, then press Enter."

if (( FAILED )); then
  warn "A check failed. Tell Claude which one, and stop here."
  exit 1
fi

finish
say "Tell Claude that all three checks passed, and whether the browser sign-in worked."
note "Don't share the password, codes, portal URL or account ID."
}

run_wizard "$@"; exit
